/**
 * Deployment metadata - typed information about the deployment
 */
export type DeploymentMetadata = {
    /**
     * Build duration in milliseconds
     */
    buildDurationMs?: number | null;
    /**
     * Docker builder used (e.g., "nixpacks", "dockerfile")
     */
    builder?: string | null;
    /**
     * Command passed to a prebuilt image entrypoint. Stored in deployment
     * metadata so redeploy, rollback, and node failover reproduce the exact
     * workload rather than falling back to the image default.
     */
    command?: Array<string> | null;
    /**
     * Deployment duration in milliseconds
     */
    deploymentDurationMs?: number | null;
    deploymentSourceType?: SourceType | null;
    /**
     * Dockerfile path if using Dockerfile builder
     */
    dockerfilePath?: string | null;
    /**
     * External image ID (reference to external_images table)
     */
    externalImageId?: number | null;
    /**
     * External Docker image reference (for docker_image source type)
     * e.g., "ghcr.io/org/app:v1.0" or "docker.io/myapp:sha-abc123"
     */
    externalImageRef?: string | null;
    /**
     * Number of files in the build output
     */
    fileCount?: number | null;
    gitPushEvent?: GitPushEvent | null;
    /**
     * Explicit deploy-time HTTP health-check path override.
     * Image/static deploys can't read `.temps.yaml`, so this lets the deploy
     * request set a custom path (e.g. "/api/healthz"). When present it takes
     * priority over any `.temps.yaml` `health.path` value. Always starts with '/'.
     */
    healthCheckPath?: string | null;
    /**
     * Total size of the built image in bytes
     */
    imageSizeBytes?: number | null;
    /**
     * Whether the image was uploaded directly (via docker save/load) rather than pulled from registry
     * When true, the PullExternalImageJob is skipped since the image is already loaded locally
     */
    imageUploadedLocally?: boolean;
    /**
     * Whether this is a rollback deployment
     */
    isRollback?: boolean;
    /**
     * Custom labels/tags for the deployment
     */
    labels?: Array<string>;
    /**
     * ID of the deployment this was rolled back from (if applicable)
     */
    rolledBackFromId?: number | null;
    runtimeOverrides?: ContainerRuntimeOverrides | null;
    /**
     * Uploaded source archive content type.
     */
    sourceBundleContentType?: string | null;
    /**
     * Uploaded source archive ID. Source archives are extracted before the
     * regular preset build pipeline and do not require Git metadata.
     */
    sourceBundleId?: number | null;
    /**
     * Uploaded source archive path in the Temps data directory.
     */
    sourceBundlePath?: string | null;
    /**
     * Static bundle content type (for proper extraction: application/gzip or application/zip)
     */
    staticBundleContentType?: string | null;
    /**
     * Static bundle ID (reference to static_bundles table, for static_files source type)
     */
    staticBundleId?: number | null;
    /**
     * Static bundle path in blob storage (for static_files source type)
     */
    staticBundlePath?: string | null;
    /**
     * Docker image ID of the locally uploaded image (sha256:...)
     * Used to verify the image exists before deployment
     */
    uploadedImageId?: string | null;
};

/**
 * What an operation record refers to, and what it produced.
 */
export type DeploymentOperationDetails = {
    deployment_id: string;
    project_id: number;
    screenshot?: DeploymentScreenshotCapture | null;
};

/**
 * Where an operation is in its lifecycle.
 *
 * An operation that does its work in the background (a screenshot capture)
 * is recorded as `Pending` when it starts and replaced by a `Completed` or
 * `Failed` record when it ends, so a caller can poll for the outcome instead
 * of being told it succeeded before anything ran.
 *
 * Published as `DeploymentOperationStatus`: `temps-projects` already owns the
 * `OperationStatus` schema name, and two schemas with one name silently
 * replace each other in the merged OpenAPI document.
 */
export type DeploymentOperationStatus = 'pending' | 'completed' | 'failed';

