    fid_p90?: number | null;
    fid_p95?: number | null;
    fid_p99?: number | null;
    inp: Array<number | null>;
    inp_p75?: number | null;
    inp_p90?: number | null;
    inp_p95?: number | null;
    inp_p99?: number | null;
    lcp: Array<number | null>;
    lcp_p75?: number | null;
    lcp_p90?: number | null;
    lcp_p95?: number | null;
    lcp_p99?: number | null;
