    /**
     * Stable unique id, `<source>:<row id>` (e.g. `deployment:123`).
     */
    id: string;
    kind: OperationKind;
    /**
     * Console path of the resource's detail page.
     */
    link: string;
    /**
     * Source-specific phase, when the source records one (restores, autofix).
     */
