/**
 * Response model for proxy logs
 */
export type ProxyLogResponse = {
    bot_name?: string | null;
    browser?: string | null;
    browser_version?: string | null;
    cache_status?: string | null;
    client_ip?: string | null;
    container_id?: string | null;
    deployment_id?: number | null;
    device_type?: string | null;
    environment_id?: number | null;
    error_message?: string | null;
    host: string;
    id: number;
    ip_geolocation_id?: number | null;
    is_bot?: boolean | null;
    is_system_request: boolean;
    /**
     * The client's JA4 TLS fingerprint, when its source gives one.
     */
    ja4?: string | null;
    /**
     * Where the JA4 came from: `direct`, `cloudflare`, `bunny`, `local` or
     * `edge`.
     */
    ja4_source?: string | null;
    method: string;
    operating_system?: string | null;
    path: string;
    project_id?: number | null;
    query_string?: string | null;
    referrer?: string | null;
    /**
     * Inbound request headers, credential values already replaced with
     * `[REDACTED]` at ingest (see [`crate::redaction`]). `None` when the entry
     * predates header capture or was written by a path that doesn't record
     * them; an empty map means "captured, but no headers", which is different
     * and worth being able to tell apart.
     *
     * A `BTreeMap` rather than a raw `serde_json::Value` so the schema stays
     * typed and the UI gets a stable alphabetical ordering for free.
     */
    request_headers?: {
        [key: string]: string;
    } | null;
    request_id: string;
    request_size_bytes?: number | null;
    request_source: string;
    /**
     * Upstream response headers, redacted on the same terms as
     * [`Self::request_headers`].
     */
    response_headers?: {
        [key: string]: string;
    } | null;
    response_size_bytes?: number | null;
    response_time_ms?: number | null;
    routing_status: string;
    session_id?: number | null;
    /**
     * The lists that hold the client, and the range on each.
     */
    shield_reasons: Array<string>;
    /**
     * What Shield would have done with the request: `log`, `challenge` or
     * `block`. `None` when no reputation list holds the client.
     */
    shield_verdict?: string | null;
    status_code: number;
    timestamp: string;
    upstream_host?: string | null;
    user_agent?: string | null;
    visitor_id?: number | null;
};

